contract InvMutTest {
    C c;
    bool called;
    address gotFrom;
    address gotTo;
    uint gotV;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public {
        address[] memory tos = new address[](1);
        tos[0] = to;
        called = false;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && called && gotFrom == from && gotTo == to && gotV == v);
    }
    fallback() external payable {
        if (msg.sig == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            (address f, address t, uint v) = abi.decode(msg.data[4:], (address, address, uint256));
            called = true;
            gotFrom = f;
            gotTo = t;
            gotV = v;
        }
    }
    receive() external payable {}
}

